"""Literal offline Malayalam rows for the handbook and merged safety guide."""

HOWTO_MALAYALAM_ROWS: dict[str, tuple[str, ...]] = {
    "ml": (
        "Go and Help എങ്ങനെ ഉപയോഗിക്കാം",
        "യാത്രക്കാർക്കും നാട്ടുകാർക്കും ഇടയിലുള്ള എല്ലാവർക്കും വേണ്ടിയുള്ള ഒരു ചെറിയ കൈപ്പുസ്തകം.",
        "1 ജൂൺ 2024ന് പുതുക്കിയതും പ്രാബല്യത്തിൽ വന്നതും",
        "Go and Help ആളുകളെ പരസ്പരം ബന്ധിപ്പിക്കുന്നു. ഇത് ആരെയും ജോലിക്കെടുക്കുകയോ മേൽനോട്ടം വഹിക്കുകയോ പരിശീലിപ്പിക്കുകയോ പരിശോധിക്കുകയോ ചെയ്യുന്നില്ല. ഓരോ കൂടിക്കാഴ്ചയും യാത്രയും ജോലിയും സ്വതന്ത്രമായി തീരുമാനിക്കുന്ന മുതിർന്നവർ തമ്മിലാണ് ക്രമീകരിക്കുന്നത്; അതിനാൽ ആരെയെങ്കിലും കാണാൻ തീരുമാനിക്കുന്നതിന് മുമ്പ് ഈ പേജ് വായിക്കുക.",
        "ഭൂപടവും അത് കാണാനുള്ള രണ്ട് രീതികളും",
        "ആപ്പിന്റെ ഹൃദയമായതിനാൽ ഭൂപടം മുഴുവൻ സ്ക്രീനിലും കാണിക്കുന്നു. നൽകുക, നേടുക എന്നീ രണ്ട് രീതികൾ അടുത്തടുത്തായി ലഭ്യമാണ്. സഹായം അഭ്യർഥിച്ചിരിക്കുന്നവരെ നൽകുക കാണിക്കുന്നു; ഓരോ അടയാളവും നിങ്ങൾക്ക് ഏറ്റെടുക്കാവുന്ന ഒരു തുറന്ന അഭ്യർഥനയാണ്. സഹായം നൽകാൻ തയ്യാറാണെന്ന് അറിയിച്ച അംഗങ്ങളെ നേടുക കാണിക്കുന്നു; അവരുടെ പ്രൊഫൈൽ വായിച്ചശേഷം അവർക്ക് സ്വീകരിക്കാവുന്ന അഭ്യർഥന പ്രസിദ്ധീകരിക്കാം.",
        "സൂം ചെയ്യാൻ വിരലുകൾ ചേർത്തോ അകറ്റിയോ നീക്കുക, ഒരു വിരൽ കൊണ്ട് വലിച്ച് ഭൂപടം നീക്കുക, രണ്ട് വിരലുകൾ കൊണ്ട് തിരിക്കുക. ഭൂപടം വടക്കുനിന്ന് തിരിഞ്ഞിരിക്കുമ്പോൾ ഭൂപട-പട്ടിക മാറ്റുസ്വിച്ചിന് സമീപം ചെറിയ ദിശാസൂചി കാണും. അതിൽ ഒരിക്കൽ തൊട്ടാൽ ഭൂപടം വീണ്ടും വടക്കോട്ട് തിരിയും.",
        "ഭൂപടം തിരക്കേറിയതായി തോന്നുമ്പോൾ പട്ടിക കാഴ്ചയിലേക്ക് മാറുക. ഒരേ വ്യക്തിയുടെ പല അഭ്യർഥനകളും ഭൂപടത്തിൽ ഒരു പ്രൊഫൈൽ അടയാളത്തിന് പിന്നിൽ കൂട്ടിച്ചേർത്താലും പട്ടിക ഓരോ അഭ്യർഥനയും പ്രത്യേകം കാണിക്കും. കൂട്ടിച്ചേർത്ത അടയാളത്തിൽ തൊട്ടാൽ ആ വ്യക്തിയുടെ അഭ്യർഥനകൾ ഓരോന്നായി കാണാം.",
        "നിങ്ങൾ എവിടെയാണെന്ന വിവരം എങ്ങനെ പങ്കിടണമെന്ന് തിരഞ്ഞെടുക്കുക",
        "എന്റെ സ്ഥാനം സജ്ജീകരിക്കുക എന്നതിൽ മൂന്ന് സ്ഥാനങ്ങളുണ്ട്; ഇടയ്ക്കൊരു നിലയില്ല. ഓഫ് തിരഞ്ഞെടുക്കുമ്പോൾ എല്ലാ ഭൂപടങ്ങളിൽനിന്നും ആളുകളെ തിരയുന്നതിൽനിന്നും നിങ്ങൾ ഒഴിവാകും: സംരക്ഷിച്ച കോർഡിനേറ്റുകൾ നിങ്ങളുടെ അക്കൗണ്ടിൽ തുടരും, പക്ഷേ ഒരു കോർഡിനേറ്റും എവിടേക്കും അയയ്ക്കില്ല. ഏകദേശം എന്ന നില നിങ്ങളുടെ കൃത്യമായ സ്ഥാനം സ്വകാര്യമായി സൂക്ഷിച്ച് 500m മുതൽ 1km അകലെയുള്ള കരയിൽ സുരക്ഷിതമായ ഒരു സ്ഥാനം മാത്രം എല്ലാ ഉപയോക്താക്കൾക്കും പ്രസിദ്ധീകരിക്കുന്നു. തത്സമയം എന്ന നില നിങ്ങളുടെ കൃത്യമായ സ്ഥാനം എല്ലാ ഉപയോക്താക്കൾക്കും പ്രസിദ്ധീകരിക്കുകയും എന്റെ സ്ഥാനം പുതുക്കുക അമർത്തുമ്പോഴെല്ലാം പുതുക്കുകയും ചെയ്യുന്നു.",
        "ഇത് വ്യക്തമായി മനസ്സിലാക്കുക: തത്സമയം എന്ന രീതിയിൽ എല്ലാ ഉപയോക്താക്കൾക്കും ഭൂപടത്തിൽ നിങ്ങളുടെ കൃത്യമായ സ്ഥാനം കാണാം; അവ്യക്തമായ ഒരു വൃത്തമല്ല. അപരിചിതർ നിങ്ങളുടെ വീടിന് പുറത്ത് നിൽക്കുന്നത് ഇഷ്ടമല്ലെങ്കിൽ വീട്ടുവിലാസത്തിൽ തത്സമയം എന്ന രീതി ഉപയോഗിക്കരുത്. ഏകദേശം തിരഞ്ഞെടുക്കുന്നതോ സമീപത്തെ ചത്വരം, ചന്ത, കഫേ എന്നിവ ഉപയോഗിക്കുന്നതോ സാധാരണയായി നല്ലതാണ്.",
        "തത്സമയ സ്ഥാനം നിങ്ങളുടെ ബ്രൗസറിനെയും ഉപകരണത്തെയും ആശ്രയിച്ചിരിക്കുന്നു. മിക്ക ബ്രൗസറുകളും സുരക്ഷിതമായ https:// വിലാസത്തിലേ ഇത് അനുവദിക്കൂ; എല്ലാ ബ്രൗസറുകളും ആദ്യം നിങ്ങളുടെ അനുമതി ചോദിക്കും. നിങ്ങൾ അനുമതി നിഷേധിക്കുകയോ സിഗ്നൽ ദുർബലമാകുകയോ ചെയ്താൽ ആപ്പ് അറിയിക്കും; ഒന്നും സംരക്ഷിക്കില്ല. സൈൻ ഇൻ ചെയ്യാത്തവർക്ക് അംഗങ്ങളുടെ കോർഡിനേറ്റുകൾ ഒരുവിധത്തിലും ലഭിക്കില്ല.",
        "സഹായത്തിനുള്ള അഭ്യർഥന പ്രസിദ്ധീകരിക്കൽ",
        "ജോലി എന്താണെന്നും ഏകദേശം എത്ര സമയം വേണ്ടിവരുമെന്നും ഏത് ഉപകരണങ്ങളോ കഴിവുകളോ ആവശ്യമാണെന്നും നിങ്ങൾക്ക് എപ്പോൾ സമയം ലഭിക്കുമെന്നും പകരമായി എന്താണ് നൽകുന്നതെന്നും വ്യക്തമായി എഴുതുക — ഭക്ഷണം, ഒരു രാത്രി താമസം, വഴികാട്ടിയുള്ള നടത്തം, പാഠം, അല്ലെങ്കിൽ നന്ദി മാത്രം. ചിത്രങ്ങൾ വളരെ സഹായകരമാണ്; വേലിയുടെയോ മതിലിന്റെയോ അടുക്കളയുടെയോ ചിത്രം നിരവധി സന്ദേശങ്ങൾ ഒഴിവാക്കും.",
        "സൗജന്യ അംഗത്വത്തിൽ ഒരേസമയം തുറന്നുവെക്കാവുന്ന അഭ്യർഥനകളുടെ എണ്ണം കുറവാണ്; ഭൂപടം യാഥാർഥ്യത്തോട് ചേർന്നുനിൽക്കാൻ അവ കുറച്ചുകാലത്തിനു ശേഷം കാലഹരണപ്പെടും. പ്രീമിയം അംഗത്വത്തിൽ ഒരേസമയം പത്ത് അഭ്യർഥനകൾ വരെ തുറന്നുവെക്കാം. ജോലി തീർന്നയുടൻ അഭ്യർഥന അടയ്ക്കുകയോ പൂർത്തിയായതായി അടയാളപ്പെടുത്തുകയോ ചെയ്യുക; അങ്ങനെ ആരും വെറുതെ യാത്ര ചെയ്യേണ്ടിവരില്ല.",
        "നിയമവിരുദ്ധമോ സുരക്ഷിതമല്ലാത്തതോ ലൈംഗികമായതോ നിങ്ങൾ സ്വയം നിരസിക്കുന്ന സാഹചര്യങ്ങളിൽ മറ്റൊരാളെ ജോലി ചെയ്യാൻ ആവശ്യപ്പെടുന്നതോ ആയ ഒന്നും പരസ്യപ്പെടുത്തരുത്. പണം കൈമാറാനോ നിക്ഷേപം നൽകാനോ രേഖകളോ അക്കൗണ്ട് വിവരങ്ങളോ കൈമാറാനോ ആരോടും ആവശ്യപ്പെടരുത്.",
        "ഒരു അഭ്യർഥന സ്വീകരിക്കുകയും സുരക്ഷിതമായി കണ്ടുമുട്ടുകയും ചെയ്യുക",
        "നിങ്ങൾ അഭ്യർഥന സ്വീകരിച്ചാൽ അത് പ്രസിദ്ധീകരിച്ച വ്യക്തിയുമായി സംഭാഷണം തുറക്കും. കൃത്യമായ കൂടിക്കാഴ്ച സ്ഥലം, സമയം, കൊണ്ടുവരേണ്ട വസ്തുക്കൾ, പ്രതിഫലമായി നൽകുന്ന കാര്യം എന്നിവ അവിടെ സമ്മതിക്കുക. നിങ്ങൾ രണ്ടുപേർക്കും ഒരേ ധാരണ ലഭിക്കാൻ വിവരങ്ങൾ ആപ്പിൽ എഴുതി സൂക്ഷിക്കുക.",
        "ആദ്യം പൊതുസ്ഥലത്ത് കണ്ടുമുട്ടുക. നിങ്ങൾ എവിടേക്കാണ് പോകുന്നതെന്നും എപ്പോൾ മടങ്ങിവരുമെന്ന് പ്രതീക്ഷിക്കുന്നുവെന്നും വിശ്വസിക്കുന്ന ഒരാളോട് പറയുക. ഫോൺ ചാർജ് ചെയ്തുവെക്കുക. പാസ്‌പോർട്ടോ താക്കോലുകളോ ബാങ്ക് വിവരങ്ങളോ ആരെയും ഏൽപ്പിക്കരുത്. ജോലി വിവരണത്തിൽനിന്ന് വ്യത്യസ്തമാണെന്ന് മനസ്സിലായാലോ എന്തെങ്കിലും തെറ്റായി തോന്നിയാലോ നിർത്തി മടങ്ങുക — തുടരാൻ നിങ്ങൾക്ക് ഒരിക്കലും ബാധ്യതയില്ല.",
        "ശാരീരികമോ വൈദ്യുതമോ ഘടനാപരമോ വൈദ്യപരമോ കുട്ടിപരിചരണവുമായി ബന്ധപ്പെട്ടതോ ആയ ജോലി ചെയ്യുന്നതിന് മുമ്പ് ഇൻഷുറൻസ്, അനുമതിപത്രങ്ങൾ, പ്രാദേശിക ചട്ടങ്ങൾ എന്നിവ പരിഗണിക്കുക. ചില രാജ്യങ്ങളിൽ ചില ജോലികൾക്ക് ലൈസൻസുള്ള വ്യക്തി ആവശ്യമാണ്; ഈ ആപ്പിലെ ഒരു പോസ്റ്റും അതിൽ മാറ്റം വരുത്തുന്നില്ല.",
        "സന്ദേശങ്ങൾ, ബന്ധങ്ങൾ, ഫോറം",
        "ജോലി സംബന്ധിച്ച സംഭാഷണങ്ങൾ ഒരു പ്രത്യേക അഭ്യർഥനയോടാണ് ബന്ധപ്പെട്ടിരിക്കുന്നത്. ബന്ധപ്പെടാനുള്ള അഭ്യർഥനകൾ വേറെയാണ്: രണ്ടുപേരും പരസ്പരം സമ്മതിച്ചാൽ അവർക്കിടയിലെ നേരിട്ടുള്ള സന്ദേശ സംഭാഷണം തുറന്നിരിക്കും.",
        "സമൂഹ ഫോറം ദീർഘമായ ചർച്ചകൾക്കുള്ള ഇടമാണ് — ചോദ്യങ്ങൾ, അനുഭവങ്ങൾ, യാത്രാമാർഗ നിർദേശങ്ങൾ, അനുഭവത്തിൽനിന്നുള്ള പ്രായോഗിക അറിവ് എന്നിവയ്ക്ക്. വായിക്കുന്നത് സൗജന്യമാണ്. വിഷയങ്ങളും അഭിപ്രായങ്ങളും എഴുതുന്നത് പ്രീമിയം അംഗത്വത്തിന്റെ ഭാഗമാണ്.",
        "കഴിയുന്നത്ര കാലം സംഭാഷണങ്ങൾ ആപ്പിനുള്ളിൽ തുടരുക. ഇതിലൂടെ രേഖ നിലനിൽക്കും; കണ്ടുമുട്ടാത്ത ഒരാൾക്ക് നിങ്ങളുടെ സ്വകാര്യ ഫോൺ നമ്പറോ ഇമെയിലോ നൽകേണ്ടിവരില്ല.",
        "അംഗത്വം",
        "സഹായം വാഗ്ദാനം ചെയ്യുന്നതും നൽകുന്നതും എല്ലായ്പ്പോഴും സൗജന്യമാണ്. പദ്ധതി തുടരാൻ സഹായിക്കുന്ന സംഭാവനയാണ് അംഗത്വം; ഇത് ഫോറം, ഒരേസമയം പത്ത് അഭ്യർഥനകൾ, മുൻഗണനാ സ്ഥാനം, വിപുലമായ തിരച്ചിൽ സൗകര്യങ്ങൾ, അധിക പ്രദർശന തിരഞ്ഞെടുപ്പുകൾ എന്നിവ ലഭ്യമാക്കുന്നു.",
        "രണ്ട് തിരഞ്ഞെടുപ്പുകളുണ്ട് — മാസ ടിക്കറ്റും വാർഷിക പാസും — രണ്ടും ഒരേ ആനുകൂല്യങ്ങൾ നൽകുന്നു. പണമടയ്ക്കൽ Stripe കൈകാര്യം ചെയ്യുന്നു; നിങ്ങളുടെ കാർഡ് വിവരങ്ങൾ ആപ്പ് കാണുകയോ സൂക്ഷിക്കുകയോ ചെയ്യുന്നില്ല. പ്രൊഫൈലിലെ ബില്ലിങ് പോർട്ടലിൽനിന്ന് എപ്പോൾ വേണമെങ്കിലും റദ്ദാക്കാം.",
        "അവലോകനങ്ങൾ",
        "ഒരു ജോലി പൂർത്തിയായ ശേഷം ഇരുവർക്കും പരസ്പരം നാല് കാര്യങ്ങളിൽ വിലയിരുത്താം: സമയനിഷ്ഠ, തൊഴിൽമനോഭാവം, കഴിവ്, സൗഹൃദപരമായ പെരുമാറ്റം — അഭ്യർഥിച്ചവർക്കും സഹായിച്ചവർക്കും ഒരുപോലെ. നാലിന്റെയും ശരാശരി കണക്കാക്കി പ്രൊഫൈലിൽ കാണിക്കുന്ന ഒറ്റ നക്ഷത്ര റേറ്റിങ്ങാക്കുന്നു.",
        "നിങ്ങൾക്ക് വായിക്കാൻ ഇഷ്ടമാകുന്ന രീതിയിൽ അവലോകനം എഴുതുക: വ്യക്തമായി, നീതിപൂർവം, സ്വകാര്യ വിവരങ്ങളില്ലാതെ. അവലോകനം നിങ്ങളുടെ യഥാർഥ അനുഭവമാണ്; ആയുധമോ ഉപകാരത്തിന് പകരമുള്ള പ്രതിഫലമോ അല്ല.",
        "റിപ്പോർട്ടുചെയ്യലും സുരക്ഷയും",
        "ആരെങ്കിലും സുരക്ഷിതമല്ലാത്തോ സത്യസന്ധമല്ലാത്തോ അധിക്ഷേപകരമോ ആയി പെരുമാറിയാൽ സംഭാഷണം നിർത്തി അവരുടെ പ്രൊഫൈലിലൂടെയോ സംഭാഷണത്തിലൂടെയോ റിപ്പോർട്ട് ചെയ്യുക. സന്ദേശങ്ങൾ സൂക്ഷിക്കുക — അവയാണ് രേഖ.",
        "അടിയന്തര സാഹചര്യത്തിൽ ആദ്യം നിങ്ങളുടെ പ്രദേശത്തെ അടിയന്തര സേവനങ്ങളുമായി ബന്ധപ്പെടുക. Go and Help അടിയന്തര സേവനമല്ല; സംഭവസ്ഥലത്ത് ഇടപെടാനും അതിന് കഴിയില്ല. അക്കൗണ്ടുകൾ പരിശോധിച്ച് ഉള്ളടക്കമോ പ്രവേശനമോ നീക്കാൻ ഞങ്ങൾക്ക് കഴിയും, എന്നാൽ ഇതിനകം സംഭവിച്ച കാര്യം തിരുത്താനാവില്ല.",
        "സുരക്ഷാ മുൻകരുതലുകൾ — ആരെയെങ്കിലും കാണുന്നതിന് മുമ്പ് ഇത് വായിക്കുക",
        "Go and Help പരിചയപ്പെടുത്താനുള്ള ഒരു ഉപകരണം മാത്രം; അതിലധികമല്ല. ഞങ്ങൾ കൂടിക്കാഴ്ചകൾക്ക് മേൽനോട്ടം വഹിക്കുകയോ സുരക്ഷയ്ക്കായി കൂടെ വരികയോ പങ്കെടുക്കുകയോ ചെയ്യുന്നില്ല; ആരുടെയും തിരിച്ചറിയൽ രേഖകൾ, ക്രിമിനൽ രേഖ, ഇൻഷുറൻസ്, ഡ്രൈവിങ് ലൈസൻസ്, തൊഴിൽയോഗ്യത എന്നിവ പരിശോധിക്കുന്നില്ല. നക്ഷത്ര റേറ്റിങ്ങുകൾ മറ്റ് അംഗങ്ങളുടെ അഭിപ്രായങ്ങൾ മാത്രമാണ് — സുരക്ഷിതത്വത്തിന്റെയോ സത്യസന്ധതയുടെയോ കഴിവിന്റെയോ ഉറപ്പല്ല. നിങ്ങളുടെ സ്വന്തം വിവേചനബുദ്ധിയാണ് നിങ്ങൾക്കുള്ള യഥാർഥ സംരക്ഷണം.",
        "നിങ്ങളുടെ കൃത്യമായ സ്ഥാനം പങ്കിടാവുന്ന ഏറ്റവും സ്വകാര്യ വിവരമാണ്",
        "തത്സമയം എന്ന നില നിങ്ങളുടെ കൃത്യമായ അക്ഷാംശവും രേഖാംശവും എല്ലാ ഉപയോക്താക്കൾക്കും പ്രസിദ്ധീകരിക്കുന്നു — അവ്യക്തമായ വൃത്തമോ സമീപപ്രദേശമോ അല്ല. ആ കോർഡിനേറ്റുകൾ നിങ്ങളുടെ കിടക്കയിലോ ഹോസ്റ്റൽ മുറിയിലോ പാർക്ക് ചെയ്ത വാഹനത്തിലോ വീടിന്റെ വാതിൽക്കലോ ആണെങ്കിൽ, നിങ്ങൾ ഉറങ്ങുന്ന സ്ഥലം അപരിചിതരോട് പറഞ്ഞിരിക്കുകയാണ്. എന്തെങ്കിലും പങ്കിടുന്നതിനു മുമ്പ് ഇതിനെക്കുറിച്ച് ചിന്തിക്കുക.",
        "പകരം സുരക്ഷിതമായ ഒരു പൊതുസ്ഥിരസ്ഥാനം തിരഞ്ഞെടുക്കുക: പ്രധാന ചത്വരം, ഗതാഗത കേന്ദ്രം, ആളുകൾ വരുന്ന കഫേയുടെ പുറംഭാഗം, ലൈബ്രറി, ചന്തയുടെ കവാടം. നിങ്ങൾ താമസിക്കുന്നിടത്തുനിന്ന് കുറച്ച് മിനിറ്റ് അകലെയും കണ്ടുമുട്ടാൻ തീരുമാനിക്കുന്ന സമയങ്ങളിൽ ആളുകളുള്ളതുമായ ഇടം തിരഞ്ഞെടുക്കുക. ഇത്തരമൊരു സ്ഥിരസ്ഥാനം നിങ്ങളുടെ വിലാസം നൽകാതെ 'ഞാൻ ഏകദേശം ഇവിടെയാണ്, ഇവിടെ കാണാം' എന്ന് സൂചിപ്പിക്കുന്നു.",
        "നിങ്ങൾക്ക് യഥാർഥത്തിൽ ആവശ്യമുള്ള സമയത്ത് മാത്രം തത്സമയ സ്ഥാനം പങ്കിടുക — ഉദാഹരണത്തിന് ഇതിനകം സമ്മതിച്ച ജോലിക്കിടെ സഹായിക്കുന്നയാൾ നിങ്ങളിലേക്കു നടക്കുമ്പോൾ — കാര്യം കഴിഞ്ഞ ഉടൻ മറച്ച നിലയിലേക്കോ പൊതുസ്ഥിരസ്ഥാനത്തേക്കോ മടങ്ങുക. തത്സമയ പങ്കിടൽ മറന്നുപോകുന്നതാണ് വീട്ടിലേക്ക് പിന്തുടരപ്പെടാനുള്ള ഏറ്റവും എളുപ്പമുള്ള വഴി.",
        "മറച്ച നില നിങ്ങളെ അംഗങ്ങളുടെ ഭൂപടങ്ങളിൽനിന്നും അംഗ തിരച്ചിലിൽനിന്നും പൂർണമായി ഒഴിവാക്കുന്നു. എന്നിരുന്നാലും നിങ്ങൾക്ക് എഴുതാനും വായിക്കാനും സഹായം നൽകാനും സന്ദേശങ്ങൾക്ക് മറുപടി നൽകാനും കഴിയും. ഒറ്റയ്ക്ക് യാത്ര ചെയ്യുമ്പോഴും ഒറ്റപ്പെട്ടിടത്ത് താമസിക്കുമ്പോഴും ഉറപ്പില്ലാത്തപ്പോഴും Go and Help ഉപയോഗിക്കുന്നതിന് മറച്ച നില തിരഞ്ഞെടുക്കുന്നത് തികച്ചും സാധാരണമാണ്.",
        "സൈൻ ഇൻ ചെയ്യാത്തവർക്ക് അംഗങ്ങളുടെ കോർഡിനേറ്റുകൾ ഒരിക്കലും ലഭിക്കില്ല; നിങ്ങളുടെ ഫോൺ നമ്പർ മറ്റ് ഉപയോക്താക്കളുമായി ഒരിക്കലും പങ്കിടുന്നുമില്ല. എന്നിരുന്നാലും പ്രസിദ്ധീകരിക്കുന്ന ഓരോ കോർഡിനേറ്റും എന്നേക്കുമായി പൊതുവായതായി കണക്കാക്കുക: ഒരാൾ അത് കണ്ടുകഴിഞ്ഞാൽ പിന്നെ തിരികെ എടുക്കാനാവില്ല.",
        "ആദ്യമായി ഒരാളെ കണ്ടുമുട്ടുമ്പോൾ",
        "മറ്റുള്ളവർക്ക് നിങ്ങളെ കാണാനാകുന്ന പകൽസമയത്തെ പൊതുസ്ഥലത്ത് കണ്ടുമുട്ടുക: ചത്വരം, സ്റ്റേഷൻ, കഫേ, കടയുടെ പ്രവേശന കവാടം. അഭ്യർഥന എത്ര യുക്തിസഹമായി തോന്നിയാലും ആദ്യ കൂടിക്കാഴ്ചയ്ക്ക് സ്വകാര്യ വീട്, പൂട്ടിയ മുറ്റം, ബോട്ട്, ഭൂഗർഭമുറി, നിർമാണസ്ഥലം, വിജനമായ റോഡ് എന്നിവിടങ്ങളിലേക്ക് പോകരുത്.",
        "വിശ്വസിക്കുന്ന ഒരാളോട് — സുഹൃത്ത്, ബന്ധു, ഹോസ്റ്റൽ സ്വീകരണ ജീവനക്കാരൻ — ആരെയാണ് കാണുന്നതെന്നും ജോലി എന്താണെന്നും എവിടെയാണെന്നും എപ്പോൾ മടങ്ങിവരുമെന്നും പറയുക. മറ്റെയാളുടെ പ്രൊഫൈൽ പേരും സംഭാഷണത്തിന്റെ സ്ക്രീൻഷോട്ടും അയയ്ക്കുക. ജോലി തീർന്നാൽ സന്ദേശമയയ്ക്കാമെന്ന് സമ്മതിക്കുക.",
        "പോകാനും മടങ്ങാനും സ്വന്തം യാത്രാസൗകര്യം ക്രമീകരിക്കുക; ഉടൻ മടങ്ങാൻ മതിയായ പണമോ ബാറ്ററിയോ കൈവശം വയ്ക്കുക. വീട്ടിലേക്ക് മടങ്ങാൻ മറ്റെയാളെ ആശ്രയിക്കരുത്; അവരുടെ കാറോ ബോട്ടോ ദയയോ മാത്രമായിരിക്കരുത് നിങ്ങളുടെ മടങ്ങിവരാനുള്ള വഴി. എത്തുന്നതിന് മുമ്പേ പുറത്തുകടക്കാനുള്ള വഴി മനസ്സിലാക്കുക.",
        "നിങ്ങൾക്ക് ആശ്വാസമാകുന്നതുവരെ Go and Help-നുള്ളിൽത്തന്നെ സംഭാഷണം തുടരുക. ആപ്പിൽനിന്ന് വേഗം മാറാൻ നിർബന്ധിക്കുന്നവരും ഒറ്റയ്ക്ക് വരാൻ സമ്മർദം ചെലുത്തുന്നവരും അവസാന നിമിഷം ആളൊഴിഞ്ഞിടത്തേക്ക് കൂടിക്കാഴ്ച മാറ്റുന്നവരും പൊതുസ്ഥലത്ത് കാണാൻ വിസമ്മതിക്കുന്നവരും പ്രധാനപ്പെട്ട സൂചനയാണ് നൽകുന്നത്. നിർത്തുക.",
        "ഏത് നിമിഷവും കാരണം പറയാതെയും ക്ഷമ ചോദിക്കാതെയും നിങ്ങൾക്ക് റദ്ദാക്കാം, പോകാം, വേണ്ടെന്ന് പറയാം. അസ്വസ്ഥത തോന്നുന്നതു മാത്രം മതിയായ കാരണമാണ്. നല്ല അയൽക്കാരൻ അത് മനസ്സിലാക്കും; അതിന് ശിക്ഷിക്കുന്ന ഒരാൾ സുരക്ഷിതനായിരുന്നില്ല.",
        "അവലോകനങ്ങൾ വായിക്കുക — സംശയബുദ്ധിയോടെയും വായിക്കുക",
        "എന്തെങ്കിലും സമ്മതിക്കുന്നതിന് മുമ്പ് മറ്റെയാളുടെ പ്രൊഫൈൽ തുറന്ന് അവർക്ക് ലഭിച്ച അവലോകനങ്ങൾ രണ്ട് നിലകളിലും വായിക്കുക: സഹായിച്ച വ്യക്തിയായും സഹായം അഭ്യർഥിച്ച വ്യക്തിയായും. നക്ഷത്രങ്ങളുടെ എണ്ണം മാത്രമല്ല, ആളുകൾ യഥാർഥത്തിൽ എഴുതിയതും ശ്രദ്ധിക്കുക.",
        "മോശം അവലോകനങ്ങളുണ്ടെങ്കിൽ പിന്മാറുക. നിർബന്ധം ചെലുത്തൽ, വൈകിവരൽ, അനാവശ്യ അടുപ്പശ്രമങ്ങൾ, പാലിക്കാത്ത വാഗ്ദാനങ്ങൾ, മദ്യപാനം, ആക്രമണസ്വഭാവം, സുരക്ഷിതമല്ലാത്ത സാഹചര്യങ്ങൾ എന്നിവ ആവർത്തിച്ച് പരാമർശിക്കപ്പെടുന്നെങ്കിൽ അതിനെ മുന്നറിയിപ്പായി കാണുക. ഒരു മോശം അവലോകനം തെറ്റിദ്ധാരണയായിരിക്കാം; ആവർത്തിക്കുന്ന പ്രവണത ഒരു പ്രവണത തന്നെയാണ്.",
        "സംശയകരമായ പ്രശംസയോടും ജാഗ്രത പുലർത്തുക: പുതുതായി തുടങ്ങിയ അക്കൗണ്ടിൽ ഒരേപോലെയുള്ള നിരവധി പ്രശംസകൾ, ഒരേ ശൈലിയിൽ എഴുതിയ അവലോകനങ്ങൾ, മാറിക്കൊണ്ടിരിക്കുന്ന വിവരണങ്ങളുള്ള പ്രൊഫൈൽ എന്നിവ ശ്രദ്ധിക്കുക. റേറ്റിങ്ങുകൾ കൃത്രിമമാക്കാം; വിവരമില്ലാത്ത പ്രൊഫൈൽ ഒന്നും വ്യക്തമാക്കുന്നില്ല.",
        "സ്ഥലങ്ങൾക്കും ഇതേ കാര്യം ബാധകമാണ്. ഒരു പ്രത്യേക വിലാസമോ സ്ഥലമോ ബാറോ പണിശാലയോ സുരക്ഷിതമല്ലെന്ന് അംഗങ്ങൾ റിപ്പോർട്ട് ചെയ്താൽ അത് വിശ്വസിച്ച് മറ്റൊരിടം തിരഞ്ഞെടുക്കുക — അല്ലാത്തപക്ഷം സന്തോഷത്തോടെ ചെയ്യുമായിരുന്ന ജോലിക്കുപോലും.",
        "റേറ്റിങ്ങുകൾ കഴിഞ്ഞ സംഭവങ്ങൾക്കുശേഷം ശേഖരിച്ച അഭിപ്രായങ്ങളാണ്. അവ പശ്ചാത്തല പരിശോധനയോ ഇൻഷുറൻസോ ആരുടെയെങ്കിലും പെരുമാറ്റത്തെക്കുറിച്ചുള്ള Go and Help-ന്റെ വാഗ്ദാനമോ അല്ല.",
        "നിങ്ങൾ നിരസിക്കേണ്ട ജോലികൾ",
        "സുരക്ഷിതമല്ലാത്ത സ്ഥലങ്ങളിൽ പ്രവേശിക്കരുത്: പണിതീരാത്തതോ ഉപേക്ഷിക്കപ്പെട്ടതോ ആയ കെട്ടിടങ്ങൾ, മേൽക്കൂരകൾ, തട്ടുകൾ, നിങ്ങൾ പരിശോധിക്കാത്ത ഏണികൾ, കുഴികൾ, ടാങ്കുകൾ, കിണറുകൾ, അടച്ചതോ വായുസഞ്ചാരമില്ലാത്തതോ ആയ ഇടങ്ങൾ, വെള്ളപ്പൊക്കജലം, നിങ്ങൾക്കില്ലാത്ത പരിശീലനവും ഉപകരണങ്ങളും ആവശ്യമായ മറ്റിടങ്ങൾ.",
        "ചെയ്യാൻ യോഗ്യതയോ ലൈസൻസോ ഇൻഷുറൻസോ ഇല്ലാത്ത ജോലി ഏറ്റെടുക്കരുത്. വൈദ്യുതപ്പണി, ഗ്യാസ്, പ്രധാന പൈപ്പുകളിലെ പ്ലംബിങ്, ഘടനാപരമായ അറ്റകുറ്റപ്പണി, മരം മുറിക്കൽ, മറ്റൊരാളുടെ വാഹനം ഓടിക്കൽ, കുട്ടിപരിചരണം, മൃഗങ്ങളെ കൈകാര്യം ചെയ്യൽ, ആശ്രിതരായ മുതിർന്നവരെ പരിചരിക്കൽ, വൈദ്യപരമോ മരുന്നുമായി ബന്ധപ്പെട്ടതോ ആയ സഹായം, രാസവസ്തുക്കളോ വൈദ്യുതോപകരണങ്ങളോ ഉൾപ്പെടുന്ന ജോലികൾ എന്നിവയ്ക്ക് യഥാർഥ നിയമ-ശാരീരിക അപകടസാധ്യതയുണ്ട്. സഹായിക്കാൻ താൽപര്യമുണ്ടെന്നത് യോഗ്യതയല്ല.",
        "നിയമവിരുദ്ധമോ സത്യസന്ധമല്ലാത്തതോ വിചിത്രമോ ആയ കാര്യങ്ങൾ നിരസിക്കുക: അറിയാത്ത പൊതികൾ കൊണ്ടുപോകൽ, അതിർത്തി കടന്ന് സാധനങ്ങൾ കൊണ്ടുപോകൽ, മറ്റൊരാളുടെ പണമോ കാർഡുകളോ രേഖകളോ ക്രിപ്റ്റോ ആസ്തികളോ കൈകാര്യം ചെയ്യൽ, പണം ശേഖരിക്കുകയോ കൈമാറുകയോ ചെയ്യൽ, ശരിയായി വിശദീകരിക്കാത്ത 'ചെറിയ സഹായങ്ങൾ' എന്നിവ.",
        "ജോലിയിൽ എന്താണ് ചെയ്യേണ്ടത്, എവിടെയാണ്, എത്ര സമയമെടുക്കും, മറ്റാരൊക്കെ ഉണ്ടാകും, എന്തെല്ലാം ഉപകരണങ്ങളുണ്ട് എന്നിവ വ്യക്തമായി ചോദിക്കുക. അവ്യക്തമായ മറുപടിയും ഒരു മറുപടിയാണ്. എത്തിയപ്പോൾ യാഥാർഥ്യം സമ്മതിച്ചതിൽനിന്ന് വ്യത്യസ്തമാണെങ്കിൽ മടങ്ങുക — സുരക്ഷിതമല്ലാത്ത ഒരു ഉച്ചതിരിഞ്ഞ് സഹിക്കേണ്ട ബാധ്യത നിങ്ങൾക്കില്ല.",
        "സാഹചര്യങ്ങൾ മാറിയാൽ നിർത്തുക: കാലാവസ്ഥ, ഇരുട്ട്, മദ്യം അല്ലെങ്കിൽ മയക്കുമരുന്ന്, അധികം ആളുകൾ എത്തുക, അല്ലെങ്കിൽ അഭ്യർഥിച്ചതിനെക്കാൾ വലുതും അപകടകരവുമായ ജോലിയായി പതുക്കെ മാറുക.",
        "അടിയന്തര സാഹചര്യങ്ങൾ",
        "അടിയന്തര സാഹചര്യത്തിൽ ആദ്യം നിങ്ങളുടെ പ്രദേശത്തെ അടിയന്തര സേവനങ്ങളുമായി ബന്ധപ്പെടുക — ഞങ്ങളെയല്ല. Go and Help-ന് അടിയന്തര ഫോൺ നമ്പറോ സുരക്ഷാസംഘമോ നിങ്ങൾക്കുവേണ്ടി ആരെയെങ്കിലും വിളിക്കാനുള്ള മാർഗമോ ഇല്ല. പോലീസിനും ആംബുലൻസിനും അഗ്നിരക്ഷാസേനയ്ക്കും മാത്രമേ നിങ്ങളെത്താൻ കഴിയൂ.",
        "ആവശ്യമാകുന്നതിനു മുമ്പ് നിങ്ങൾ ഉള്ള സ്ഥലത്തെ അടിയന്തര നമ്പർ മനസ്സിലാക്കുക. യൂറോപ്യൻ യൂണിയനിലും മറ്റു പല രാജ്യങ്ങളിലും 112 പ്രവർത്തിക്കുന്നു; മറ്റിടങ്ങളിൽ 999, 911, 000 തുടങ്ങിയ നമ്പറുകളാണ് ഉപയോഗിക്കുന്നത്. ചാർജുള്ള ഫോണോ ഡാറ്റാ ബന്ധമോ ആവശ്യമില്ലാത്തിടത്ത് നമ്പർ കുറിച്ചുവെക്കുക.",
        "ഫോൺ ചാർജ് ചെയ്തുവെക്കുക, ഓഫ്‌ലൈൻ ഭൂപടമോ വിലാസക്കുറിപ്പുകളോ കൈവശം വയ്ക്കുക, താമസിക്കുന്ന സ്ഥലത്തിന്റെ പേരും തെരുവും മനസ്സിലാക്കുക, അടിയന്തര ഉപയോഗത്തിനുള്ള കുറച്ച് പണം പേഴ്സിൽനിന്ന് വേർതിരിച്ച് സൂക്ഷിക്കുക.",
        "നിങ്ങൾക്ക് പരിക്കേൽക്കുകയോ ഭീഷണിയുണ്ടാകുകയോ കൊള്ളയടിക്കപ്പെടുകയോ ചെയ്താൽ പ്രാദേശിക അധികാരികളെ അറിയിച്ച് റഫറൻസ് നമ്പർ സൂക്ഷിക്കുക. തുടർന്ന് അംഗത്തെ ഞങ്ങളോടും റിപ്പോർട്ട് ചെയ്യുക; അക്കൗണ്ടിൽ നടപടി സ്വീകരിക്കാം.",
        "ഉപദ്രവം, റിപ്പോർട്ട് ചെയ്യൽ, തടയൽ",
        "Go and Help-ൽ ആരും ലൈംഗിക സമീപനങ്ങൾ, വംശീയത, ഭീഷണികൾ, അധിക്ഷേപങ്ങൾ, ആവർത്തിച്ചുള്ള അനാവശ്യ ബന്ധപ്പെടൽ, മദ്യപിക്കാൻ സമ്മർദം, തുടരാൻ സമ്മർദം, പണം, നഗ്നചിത്രങ്ങൾ, സ്വകാര്യ രേഖകൾ എന്നിവയുടെ ആവശ്യങ്ങൾ സഹിക്കേണ്ടതില്ല. ഇതിലൊന്നും ഉൾപ്പെടുന്ന സഹായ അഭ്യർഥനയ്ക്ക് ന്യായീകരണമില്ല.",
        "മറുപടി നൽകുന്നത് നിർത്തുക, തെളിവുകൾ സൂക്ഷിക്കുക, അവരുടെ പ്രൊഫൈലിലൂടെയോ സംഭാഷണത്തിലൂടെയോ അംഗത്തെ റിപ്പോർട്ട് ചെയ്യുക. സ്ക്രീൻഷോട്ടുകളും തീയതികളും കൃത്യമായ വാക്കുകളും പൊതുവായ പരാതിയേക്കാൾ ഞങ്ങൾക്ക് സഹായകരമാണ്. റിപ്പോർട്ട് ചെയ്യുന്നതിനു മുമ്പ് സംഭാഷണം മായ്ക്കരുത്.",
        "തടയൽ ആ വ്യക്തിയെ നിങ്ങളുടെ സംഭാഷണങ്ങളിൽനിന്ന് നീക്കി വീണ്ടും ബന്ധപ്പെടുന്നത് തടയും. റിപ്പോർട്ട് ചെയ്താൽ ഞങ്ങൾക്കും വിവരം ലഭിക്കും; അക്കൗണ്ട് പരിശോധിക്കാനും നിയന്ത്രിക്കാനും Go and Help-ൽനിന്ന് നീക്കാനും കഴിയും. ആരെങ്കിലും നിങ്ങളെ ഭയപ്പെടുത്തുമ്പോൾ രണ്ടും ചെയ്യുക.",
        "വലിയ ദോഷമൊന്നും സംഭവിക്കാതിരുന്നാലും മോശം അനുഭവങ്ങൾ റിപ്പോർട്ട് ചെയ്യുക — അടുത്ത യാത്രക്കാരനെ സംരക്ഷിക്കാൻ അത്തരത്തിലുള്ള തലനാരിഴയ്ക്കുള്ള സംഭവങ്ങളാണ് സഹായിക്കുന്നത്. സത്യസന്ധമായ അവലോകനങ്ങളും എഴുതുക: ശാന്തവും വസ്തുതാപരവുമായ നിങ്ങളുടെ വിവരണം കോപത്തോടെ എഴുതിയതിനെക്കാൾ വിലപ്പെട്ടതാണ്.",
        "ഫോൺ, വിലാസം, രേഖകൾ, പണം എന്നിവ സംരക്ഷിക്കുക",
        "ഫോൺ തുറന്ന നിലയിൽ മറ്റൊരാൾക്ക് കൊടുക്കരുത്, രഹസ്യവാക്കുകളോ സ്ഥിരീകരണ കോഡുകളോ പങ്കിടരുത്, നിങ്ങളുടെ അക്കൗണ്ടുകളിൽ 'ഒന്ന് പരിശോധിക്കട്ടെ' എന്ന് മറ്റൊരാളെ അനുവദിക്കരുത്. ഫോണിലേക്ക് വന്ന കോഡ് ചോദിക്കുന്നവർ നിങ്ങളിൽനിന്ന് എന്തെങ്കിലും കൈക്കലാക്കാൻ ശ്രമിക്കുകയാണ്.",
        "വീട്ടുവിലാസം, ഹോസ്റ്റൽ മുറിനമ്പർ, ജോലിസ്ഥലം, പാസ്‌പോർട്ട്, വിസ, തിരിച്ചറിയൽ കാർഡ്, യാത്രാരേഖകൾ എന്നിവ സ്വകാര്യമായി സൂക്ഷിക്കുക. ആർക്കുവേണ്ടിയും അവയുടെ ചിത്രം എടുക്കരുത്, ജാമ്യമോ നിക്ഷേപമോ ആയി നൽകുകയോ ജോലി ചെയ്യുമ്പോൾ മറ്റൊരാളെ കൈവശം വയ്ക്കാൻ അനുവദിക്കുകയോ അരുത്.",
        "നിങ്ങളുടെ ഫോൺ നമ്പർ മറ്റ് ഉപയോക്താക്കളുമായി ഒരിക്കലും പങ്കിടുന്നില്ല. അത് നിങ്ങളുടെ സ്വന്തം അക്കൗണ്ടിനായി മാത്രമാണ് സൂക്ഷിക്കുന്നത്; അംഗങ്ങൾക്കോ അതിഥികൾക്കോ അത് കാണാനാവില്ല. നിങ്ങൾക്ക് മറ്റൊരാൾക്ക് നമ്പർ നൽകണമെങ്കിൽ സ്വയം നൽകുക, ആശ്വാസമുള്ളപ്പോൾ മാത്രം നൽകുക.",
        "ഒരു ജോലിക്കായി Go and Help ഒരിക്കലും പണം ചോദിക്കില്ല; പണം ശേഖരിക്കാൻ അപരിചിതനെ അയയ്ക്കുകയും ഇല്ല. അംഗങ്ങൾക്ക് നിക്ഷേപമോ സമ്മാന കാർഡുകളോ ക്രിപ്റ്റോ ആസ്തികളോ ബാങ്ക് കൈമാറ്റമോ അയയ്ക്കരുത്; അധികം പണം നൽകി തിരിച്ചയക്കാൻ ആവശ്യപ്പെടുന്ന ഇടപാടുകൾ സ്വീകരിക്കരുത്. സൗഹൃദസംഭാഷണത്തെ നിങ്ങളുടെ സാമ്പത്തിക കാര്യങ്ങളിലേക്കോ പ്രണയബന്ധത്തിലേക്കോ തിരിക്കുന്നവരെക്കുറിച്ച് ജാഗ്രത പുലർത്തുക.",
        "അംഗത്വത്തിനുള്ള പണമടയ്ക്കൽ Stripe കൈകാര്യം ചെയ്യുന്നു. സന്ദേശത്തിൽ നിങ്ങളുടെ മുഴുവൻ കാർഡ് നമ്പറോ PIN-ഓ ബാങ്കിങ് രഹസ്യവാക്കോ ഞങ്ങൾ ഒരിക്കലും ചോദിക്കില്ല; ഞങ്ങളുടെ പേരിൽ സംസാരിക്കുന്നവരും ചോദിക്കരുത്.",
        "അതിർത്തികൾ, പ്രാദേശിക നിയമം, ആചാരങ്ങൾ",
        "Go and Help ലോകമെമ്പാടും ഉപയോഗിക്കുന്നു; ഒരു രാജ്യത്ത് സാധാരണമായത് അടുത്ത രാജ്യത്ത് നിയമവിരുദ്ധമായിരിക്കാം. പണം ലഭിക്കാതിരുന്നാലും ഭക്ഷണം, താമസസ്ഥലം, യാത്രാസഹായം എന്നിവയ്ക്കായി ജോലി ചെയ്യുന്നതോ പ്രതിഫലം സ്വീകരിക്കുന്നതോ വിസയുടെയോ കുടിയേറ്റനിയമങ്ങളുടെയോ ലംഘനമായേക്കാം. നിങ്ങളുടെ വിസാ നിബന്ധനകൾ പരിശോധിക്കുക; അതിന്റെ ഉത്തരവാദിത്തം നിങ്ങളുടേതാണ്, ഞങ്ങളുടേതല്ല.",
        "പ്രാദേശിക നിയമങ്ങളെ ഗൗരവത്തോടെ കാണുക: നികുതിയും റിപ്പോർട്ട് ചെയ്യലും, ഇൻഷുറൻസ് ആവശ്യകതകൾ, തൊഴിൽ-വാഹന ലൈസൻസുകൾ, മദ്യ-മയക്കുമരുന്ന് നിയമങ്ങൾ, ചിത്രമെടുക്കുന്നതിനുള്ള നിയന്ത്രണങ്ങൾ, പ്രതിഷേധ-കർഫ്യൂ നിയമങ്ങൾ, ആർക്കാണ് ജോലി ചെയ്യാൻ അനുമതിയുള്ളത് തുടങ്ങിയ ചട്ടങ്ങൾ. വിദേശത്ത് നിയമം അറിയില്ലെന്നത് അപൂർവമായേ പ്രതിരോധമാകൂ.",
        "പ്രാദേശിക ആചാരങ്ങളും അപകടസാധ്യതകളും മനസ്സിലാക്കുക: ഇരുട്ടിനു ശേഷം സുരക്ഷിതമല്ലാത്ത പ്രദേശങ്ങൾ, അനാവശ്യ ശ്രദ്ധ ക്ഷണിക്കുന്ന വസ്ത്രധാരണവും പെരുമാറ്റവും, വെള്ളത്തിന്റെയും ഭക്ഷണത്തിന്റെയും സുരക്ഷ, മൃഗങ്ങൾ, ചൂട്, കൊടുങ്കാറ്റ്, വെള്ളപ്പൊക്കം തുടങ്ങിയ കാലാവസ്ഥാപരമായ അപകടങ്ങൾ.",
        "ഒരു ജോലിക്കായി അതിർത്തി കടക്കുമ്പോൾ പ്രത്യേക ജാഗ്രത വേണം: മറ്റൊരാൾക്കായി ഒന്നും കൊണ്ടുപോകരുത്, രേഖകൾ കൈവശം വയ്ക്കുക, തിരികെ വരാനാകുമെന്ന് ഉറപ്പാക്കുക.",
        "Go and Help ചെയ്യാത്ത കാര്യങ്ങൾ",
        "ഞങ്ങൾ കൂടിക്കാഴ്ചകൾക്ക് മേൽനോട്ടം വഹിക്കുകയോ പങ്കെടുക്കുകയോ നിരീക്ഷിക്കുകയോ ചെയ്യുന്നില്ല. നിങ്ങളുടെ ക്രമീകരണത്തിന് പിന്നിൽ അനുഗമിക്കുന്നയാളോ നിരീക്ഷകനോ ഇൻഷുറൻസോ ഇല്ല. മുതിർന്നവർ ക്രമീകരിക്കുന്നു, മുതിർന്നവർ അത് ചെയ്യുന്നു, അപകടസാധ്യതയും മുതിർന്നവർ ഏറ്റെടുക്കുന്നു.",
        "Go and Help-ലെ സ്ഥിരീകരിച്ച അടയാളം അംഗം തന്റെ ഇമെയിൽ വിലാസം സ്ഥിരീകരിച്ചു എന്നൊന്നേ അർഥമാക്കുന്നുള്ളൂ. അത് തിരിച്ചറിയൽ പരിശോധനയോ ക്രിമിനൽ രേഖാ പരിശോധനയോ യോഗ്യതാ പരിശോധനയോ സ്വഭാവസാക്ഷ്യപത്രമോ അല്ല.",
        "നക്ഷത്ര റേറ്റിങ്ങുകളും ദയാപോയിന്റുകളും സഹായകരമായ അവലോകനങ്ങളും മുമ്പ് നടന്ന കാര്യങ്ങളാണ് വിവരിക്കുന്നത്. ഒരാൾ അടുത്തതായി എന്തു ചെയ്യുമെന്ന് അവ പ്രവചിക്കില്ല; കൂടിക്കാഴ്ച സുരക്ഷിതമായിരിക്കുമെന്ന് ഞങ്ങളുടെ വാഗ്ദാനവുമല്ല.",
        "ഒരു സന്ദേശത്തിലോ കൂടിക്കാഴ്ച സ്ഥലത്തോ എത്തിയശേഷമോ എന്തെങ്കിലും തെറ്റായി തോന്നിയാൽ ആ തോന്നൽ വിശ്വസിക്കുക, അവിടെനിന്ന് മാറുക, ഞങ്ങളെ അറിയിക്കുക. ഒരു ജോലിയോ സഹായമോ ഭക്ഷണമോ താമസമോ നിങ്ങളുടെ സുരക്ഷയെക്കാൾ വിലപ്പെട്ടതല്ല.",
    ),
}
